const e = $('Inicio').first().json;
const a = $input.first().json;
const tools = (a.intermediateSteps ?? []).map(s => s.action?.tool).filter(Boolean);
const error = a.error ? String(a.error.message ?? a.error).slice(0, 1000) : null;
const respuesta = a.output || 'Tuve un problema para responder. Intenta de nuevo en un minuto.';
const latencia = e.timestamp ? Date.now() - Date.parse(e.timestamp) : null;

return [{ json: {
  respuesta,
  acciones_locales: [],
  log: [e.session_id ?? null, e.canal ?? null, e.texto ?? '', JSON.stringify(tools), respuesta, latencia, error],
} }];
